<?php
namespace App\Domain\Network\Commerce;
use App\Domain\Network\Commerce\Models\{NetworkCommercialProduct,TenantSaasOrder};use App\Domain\Network\Tenancy\Models\Tenant;use App\Models\User;use Illuminate\Support\Facades\DB;
final class TenantSaasOrderService{public function create(Tenant$t,User$u,NetworkCommercialProduct$p,string$key):TenantSaasOrder{abort_unless($p->is_active,404);return DB::transaction(function()use($t,$u,$p,$key){$existing=TenantSaasOrder::where('tenant_id',$t->id)->where('purchase_key',$key)->first();if($existing)return$existing;$snapshot=['code'=>$p->code,'name'=>$p->name,'description'=>$p->description,'type'=>$p->type,'billing_type'=>$p->billing_type,'plan_id'=>$p->plan_id,'module_id'=>$p->module_id,'included_operations'=>$p->included_operations,'metadata'=>$p->metadata??[]];return TenantSaasOrder::create(['tenant_id'=>$t->id,'commercial_product_id'=>$p->id,'created_by_user_id'=>$u->id,'purchase_key'=>$key,'status'=>'PENDING_PAYMENT','payment_status'=>'PENDING','quantity'=>1,'unit_amount'=>$p->price,'subtotal'=>$p->price,'tax_amount'=>0,'total_amount'=>$p->price,'currency'=>$p->currency,'purchase_snapshot'=>$snapshot,'expires_at'=>now()->addHour()]);});}}
